    {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
     "code": {"type": "string", "default": "import datetime\nimport json\nimport re\n\nWEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nH = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']\n\nORDINAL_WORDS = ['first', 'second', 'third', 'fourth', 'fifth', 'sixth', 'seventh', 'eighth', 'ninth', 'tenth',\n                 'eleventh', 'twelfth', 'thirteenth', 'fourteenth', 'fifteenth', 'sixteenth', 'seventeenth',\n                 'eighteenth', 'nineteenth', 'twentieth']\n\ndef parse_now(value):\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now')\n\ndef is_business_day(d, holidays):\n    return d.weekday() < 5 and d not in holidays\n\ndef next_business_day(d, holidays, include_today=False):\n    if include_today and is_business_day(d, holidays):\n        return d\n    d = d + datetime.timedelta(days=1)\n    while not is_business_day(d, holidays):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef week_monday(d):\n    return d - datetime.timedelta(days=d.weekday())\n\ndef weekday_in_week(d, weekday_name, weeks_ahead=0):\n    idx = WEEKDAYS.index(str(weekday_name).strip().lower())\n    return week_monday(d) + datetime.timedelta(days=7 * int(weeks_ahead) + idx)\n\ndef parse_date_words(text, today):\n    s = str(text or '').strip().lower()\n    m = re.search(r'(\\d{4})-(\\d{1,2})-(\\d{1,2})', s)\n    if m:\n        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))\n    m = re.search(r'\\b(\\d{1,2})[./](\\d{1,2})[./](\\d{2,4})\\b', s)\n    if m:\n        y = int(m.group(3))\n        return datetime.date(y + 2000 if y < 100 else y, int(m.group(2)), int(m.group(1)))\n    for i, name in enumerate(MONTHS):\n        m = re.search(r'\\b(\\d{1,2})(st|nd|rd|th)?\\s+(of\\s+)?' + name[:3] + r'[a-z]*\\b', s) or \\\n            re.search(r'\\b' + name[:3] + r'[a-z]*\\s+(the\\s+)?(\\d{1,2})(st|nd|rd|th)?\\b', s)\n        if m:\n            day = int(m.group(1) if m.group(1) and m.group(1).isdigit() else m.group(2))\n            cand = datetime.date(today.year, i + 1, day)\n            return cand if cand >= today else datetime.date(today.year + 1, i + 1, day)\n    return None\n\ndef ordinals_to_digits(text):\n    s = str(text or '').lower()\n    s = re.sub(r'\\bthirty[\\s-]+first\\b', '31th', s)\n    s = re.sub(r'\\bthirtieth\\b', '30th', s)\n    for i, w in enumerate(ORDINAL_WORDS[:9], 1):\n        s = re.sub(r'\\btwenty[\\s-]+' + w + r'\\b', str(20 + i) + 'th', s)\n    for i, w in enumerate(ORDINAL_WORDS, 1):\n        s = re.sub(r'\\b' + w + r'\\b', str(i) + 'th', s)\n    return s\n\ndef resolve_date_words(text, today, next_weekday_weeks=1):\n    s = ordinals_to_digits(str(text or '').strip().lower())\n    if not s:\n        return None\n    explicit = parse_date_words(s, today)\n    if explicit is not None:\n        return explicit\n    m = re.search(r'\\b(\\d{1,2})(st|nd|rd|th)\\b', s)\n    if m:\n        day = int(m.group(1))\n        for k in range(0, 3):\n            y, mo = today.year + (today.month - 1 + k) // 12, (today.month - 1 + k) % 12 + 1\n            try:\n                cand = datetime.date(y, mo, day)\n            except ValueError:\n                continue\n            if cand >= today:\n                return cand\n        return None\n    if 'day after tomorrow' in s:\n        return today + datetime.timedelta(days=2)\n    if 'tomorrow' in s:\n        return today + datetime.timedelta(days=1)\n    if re.search(r'\\btoday\\b|\\bnow\\b', s):\n        return today\n    for i, name in enumerate(WEEKDAYS):\n        if re.search(r'\\b' + name + r'\\b', s):\n            if re.search(r'\\bnext\\s+' + name, s):\n                return weekday_in_week(today, name, next_weekday_weeks)\n            if re.search(r'\\bthis\\s+' + name, s):\n                return weekday_in_week(today, name, 0)\n            d = weekday_in_week(today, name, 0)\n            return d if d >= today else d + datetime.timedelta(days=7)\n    return parse_date_words(s, today)\n\ndef spoken_date(d):\n    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()\n\ndef money(amount):\n    return '{:,.2f}'.format(round(float(amount), 2))\n\ntry:\n    now = parse_now(vars.get('now'))\n    today = now.date()\n    hol = set(datetime.date.fromisoformat(x) for x in H)\n    f = json.loads(vars.get('facts_json') or '{}')\n    st = json.loads(vars.get('neg_json') or '{}')\n    past_due = float(f['past_due'])\n    floor = float(f['floor'])\n    deadline = datetime.date.fromisoformat(f['deadline'])\n    a1 = datetime.date.fromisoformat(f['attempt1'])\n    attempts = int(f['attempts'])\n    ans = str(vars.get('offer_answer') or 'stay')\n    if vars.get('confirm_answer') == 'change':\n        ans = 'own'\n    if vars.get('help_answer') == 'own_terms':\n        ans = 'own'\n        st['no_persuade'] = 1\n    words = str(vars.get('agreed_date_words') or '').strip()\n    raw = str(vars.get('agreed_amount') or '').strip()\n    cur_amount = float(st.get('cur_amount', past_due))\n    cur_date = datetime.date.fromisoformat(st.get('cur_date', today.isoformat()))\n    refused = st.get('refused', [])\n    st['refused'] = refused\n\n    def propose(amount, day, lead):\n        st['cur_amount'] = amount\n        st['cur_date'] = day.isoformat()\n        text = lead + 'Can you pay ' + money(amount) + ' on ' + spoken_date(day) + '?'\n        if amount < past_due:\n            text = text + ' The rest of the past-due amount stays overdue.'\n        vars['offer_text'] = text\n        vars['neg_state'] = 'offer'\n\n    def refusal(lead):\n        if st.get('no_persuade'):\n            vars['close_outcome'] = 'no_promise'\n            vars['close_reason'] = 'hardship'\n            vars['neg_state'] = 'end'\n            return\n        while True:\n            st['used'] = int(st.get('used', 0)) + 1\n            if st['used'] == 1:\n                amt, day = (floor if st.get('too_much') else past_due), a1\n            elif st['used'] == 2 and attempts >= 2:\n                amt, day = floor, deadline\n            else:\n                vars['close_outcome'] = 'no_promise'\n                vars['close_reason'] = 'refused'\n                vars['neg_state'] = 'end'\n                return\n            if (money(amt) + '|' + day.isoformat()) not in refused:\n                propose(amt, day, lead)\n                return\n\n    if ans == 'refused' or (ans == 'too_much' and st.get('floor_offered')):\n        refused.append(money(cur_amount) + '|' + cur_date.isoformat())\n        if ans == 'too_much':\n            st['too_much'] = 1\n        refusal('')\n    else:\n        lead = ''\n        amount = cur_amount\n        if ans == 'too_much':\n            st['too_much'] = 1\n            st['floor_offered'] = 1\n            amount = floor\n            lead = 'I understand. '\n        elif raw:\n            try:\n                amount = float(raw.replace(',', ''))\n            except ValueError:\n                pass\n        day = cur_date\n        if ans == 'vague':\n            day = None\n        elif words:\n            day = resolve_date_words(words, today)\n        if amount > past_due:\n            amount = past_due\n        done = False\n        if amount < floor:\n            if st.get('floor_offered'):\n                refused.append(money(floor) + '|' + cur_date.isoformat())\n                refusal('That amount cannot be recorded. ')\n                done = True\n            else:\n                st['floor_offered'] = 1\n                amount = floor\n                lead = 'That amount cannot be recorded. The lowest amount I can record is ' + money(floor) + '. '\n        if not done:\n            if day is None:\n                if not st.get('vague_asked'):\n                    st['vague_asked'] = 1\n                    st['cur_amount'] = amount\n                    vars['offer_text'] = lead + 'Which exact day could you pay?'\n                    vars['neg_state'] = 'offer'\n                else:\n                    propose(amount, deadline, lead + 'The latest date I can record is ' + spoken_date(deadline) + '. ')\n            else:\n                fixed = day\n                if day < today:\n                    fixed = next_business_day(today, hol, True)\n                    lead = lead + 'The payment date must be today or later. '\n                elif day > deadline:\n                    fixed = deadline\n                    lead = lead + 'The latest date I can record is ' + spoken_date(deadline) + '. '\n                elif not is_business_day(day, hol):\n                    fixed = next_business_day(day, hol)\n                    if fixed > deadline:\n                        fixed = deadline\n                        lead = lead + 'The latest date I can record is ' + spoken_date(deadline) + '. '\n                    else:\n                        lead = lead + spoken_date(day) + ' is not a business day. The next business day is ' + spoken_date(fixed) + '. '\n                if fixed > deadline:\n                    fixed = deadline\n                if lead:\n                    propose(amount, fixed, lead)\n                else:\n                    st['cur_amount'] = amount\n                    st['cur_date'] = fixed.isoformat()\n                    vars['promise_amount'] = round(amount, 2)\n                    vars['promise_date'] = fixed.isoformat()\n                    vars['readback_text'] = 'To confirm: for your ' + f['label'] + ', ' + money(amount) + ' on ' + spoken_date(fixed) + '. Do you confirm?'\n                    vars['neg_state'] = 'readback'\n    vars['neg_json'] = json.dumps(st)\nexcept Exception:\n    vars['offer_text'] = 'Which exact day could you pay?'\n    vars['neg_state'] = 'offer'\nvars['offer_answer'] = 'stay'\nvars['confirm_answer'] = 'stay'\nvars['help_answer'] = 'stay'\nvars['agreed_amount'] = ''\nvars['agreed_date_words'] = ''\nvars['topic'] = 'none'\n"},
