      "answer": {"type": "string", "description": "date_of_birth: YYYY-MM-DD (numbers only are day, month, year). phone_last4: four digits.", "default": "{{id_answer}}"}}}}}},
     "pre_process_code": "import re\ntry:\n    b = config.get('body')\n    if isinstance(b, dict):\n        a = str(b.get('answer') or '').strip()\n        if b.get('field') == 'phone_last4':\n            digits = ''.join(c for c in a if c.isdigit())\n            b['answer'] = digits[-4:] if len(digits) >= 4 else digits\n        elif b.get('field') == 'date_of_birth':\n            m = re.match(r'^(\\d{1,2})[./ -](\\d{1,2})[./ -](\\d{4})$', a)\n            if m:\n                b['answer'] = m.group(3) + '-' + m.group(2).zfill(2) + '-' + m.group(1).zfill(2)\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    sc = str(result.get('status_code') or '')\n    if not isinstance(d, dict) or sc.startswith('5'):\n        result['what_to_do_next'] = 'The check did not go through and nothing was counted. Call verify_identity again with the same answer.'\n    elif str(d.get('all_verified')).lower() == 'true':\n        vars['id_state'] = 'passed'\n        d['what_to_do_next'] = 'Both questions passed. Say thank you in a few words only.'\n    elif str(d.get('wrong_answers_left')) == '0':\n        vars['id_state'] = 'failed'\n        d['what_to_do_next'] = 'The check failed. Say nothing about the account.'\n    elif d.get('hint') == 'day_month_swapped':\n        d['what_to_do_next'] = 'Ask the customer to say the month of birth as a word, then check again. This does not count as a wrong answer.'\n    elif str(d.get('ok')).lower() == 'false':\n        d['what_to_do_next'] = 'The answer could not be read. Ask the same question again.'\n    elif str(d.get('verified')).lower() == 'true':\n        d['what_to_do_next'] = 'Correct. Now ask for the last four digits of the phone number on file.'\n    else:\n        d['what_to_do_next'] = 'That answer is not correct. Ask the same question once more.'\nexcept Exception:\n    pass\n"},
