{
 "initial_node": "setup",
 "system_prompt": "You are the digital assistant of Freya Bank, calling a customer. Speak English, one or two short sentences per turn, one question at a time. Before identity is verified never say collections, debt, payment, an amount or the product, to anyone, including relatives. A relative or other person may not answer security questions and may not be told anything about the account, even if they offer to pay. If asked whether you are a robot or an AI, say you are Freya Bank's digital assistant and continue. If asked whether this is a scam, say they can verify the call by phoning Freya Bank's customer service number, and continue. If you cannot answer a question from the facts you were given, say you do not have that information. Never invent figures, dates or reasons. Never offer a discount, a waiver, an instalment plan or any term you were not given. Never ask the customer how much they can pay. A recorded promise cannot be changed or cancelled in this call: if asked, say they can change it in the mobile app. Say a promise is recorded only after the system confirms it. After every tool result, either speak to the customer or call the next tool: never end a turn with nothing. Call one tool per message. Follow what_to_do_next in a tool result.",
 "test_variables": {
  "customer_id": "c_4f2a_demo",
  "first_name": "Daniel",
  "last_name": "Reyes",
  "title": "Mr",
  "now": "2026-10-14T11:00"
 },
 "nodes": {
  "setup": {
   "name": "setup",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "opening",
   "on_enter": {"type": "silent"},
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
     "code": {"type": "string", "default": "import datetime\n\nWEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nH = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']\n\ndef parse_now(value):\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now')\n\ndef is_business_day(d, holidays):\n    return d.weekday() < 5 and d not in holidays\n\ndef next_business_day(d, holidays):\n    d = d + datetime.timedelta(days=1)\n    while not is_business_day(d, holidays):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef spoken_date(d):\n    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()\n\ntry:\n    now = parse_now(vars.get('now'))\n    today = now.date()\n    hol = set(datetime.date.fromisoformat(x) for x in H)\n    nxt = next_business_day(today, hol)\n    parts = []\n    if now.hour < 19:\n        start = now + datetime.timedelta(minutes=1)\n        s = '10:00' if start.hour < 10 else start.strftime('%H:%M')\n        parts.append('today, ' + spoken_date(today) + ' (date ' + today.isoformat() + '), from ' + s + ' to 19:00')\n    parts.append(spoken_date(nxt) + ' (date ' + nxt.isoformat() + '), from 10:00 to 19:00')\n    vars['callback_window_text'] = 'It is now ' + spoken_date(today) + ', ' + now.strftime('%H:%M') + '. A callback can only be booked ' + ' or '.join(parts) + ', both ends included. No other day or time is allowed.'\n    vars['today_spoken'] = spoken_date(today)\nexcept Exception:\n    vars['callback_window_text'] = 'A callback can only be booked between 10:00 and 19:00 on the next business day.'\n    vars['today_spoken'] = ''\nvars['close_outcome'] = 'not_reached'\nvars['close_reason'] = 'unclear'\nvars['promise_count'] = '0'\nvars['call_state'] = 'open'\nvars['id_state'] = 'open'\nvars['neg_state'] = 'none'\nvars['transfer_state'] = 'none'\nvars['record_result'] = 'none'\nvars['record_tries'] = '0'\nvars['topic'] = 'none'\n"},
     "timeout_ms": {"type": "number", "default": 10000}}}}}
   ],
   "transitions": [{"target_node": "opening", "description": "always", "condition": {"operator": "always"}}]
  },
  "opening": {
   "name": "opening",
   "node_type": "conversation",
   "on_enter": {"type": "tts", "text": "Hello, I am a digital assistant calling from Freya Bank, and this call is recorded. Am I speaking with {{title}} {{last_name}}?"},
   "on_enter_first_entry_only": true,
   "task_message": "Find out whether you are speaking with {{title}} {{last_name}}. Only yes, that's me, speaking, or their own name confirms it. Hello, go ahead or who is this do not. If unclear, answer any question first, then ask once more: Am I speaking with {{title}} {{last_name}}? Say nothing about why you are calling. No tool call is allowed except end_call right after a goodbye.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 10000}, "function": {"name": "end_call", "handler": "__function__:end_call", "description": "Ends the call. CALL it right after you said goodbye, with no other text.", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}
   ],
   "extraction_schema": [
    {"name": "who", "type": "string", "enum_values": ["unclear", "customer", "someone_else", "wrong_number", "deceased"], "description": "customer: the person says yes, that's me, speaking, or their own name. someone_else: another person answered (relative, colleague). wrong_number: the number does not belong to the customer. deceased: the customer has died. unclear: anything else (hello, go ahead, who is this).", "min_confidence": 0.6}
   ],
   "max_node_turns": 2,
   "max_turn_transition": "end_goodbye",
   "transitions": [
    {"target_node": "identity", "description": "The customer confirmed", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "customer"}]}},
    {"target_node": "deceased_prep", "description": "The customer has died", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "deceased"}]}},
    {"target_node": "wrong_prep", "description": "Wrong number", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "wrong_number"}]}},
    {"target_node": "third_party_prep", "description": "Someone else answered", "condition": {"logic": "or", "conditions": [{"variable": "who", "operator": "equals", "operand": "someone_else"}]}}
   ]
  },
  "wrong_prep": {
   "name": "wrong_prep",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "end_goodbye",
   "on_enter": {"type": "silent"},
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
     "code": {"type": "string", "default": "vars['close_outcome'] = 'not_reached'\nvars['close_reason'] = 'wrong_number'\n"},
     "timeout_ms": {"type": "number", "default": 10000}}}}}
   ],
   "transitions": [{"target_node": "end_goodbye", "description": "always", "condition": {"operator": "always"}}]
  },
  "deceased_prep": {
   "name": "deceased_prep",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "end_deceased",
   "on_enter": {"type": "silent"},
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
     "code": {"type": "string", "default": "vars['close_outcome'] = 'not_reached'\nvars['close_reason'] = 'deceased'\n"},
     "timeout_ms": {"type": "number", "default": 10000}}}}}
   ],
   "transitions": [{"target_node": "end_deceased", "description": "always", "condition": {"operator": "always"}}]
  },
  "third_party_prep": {
   "name": "third_party_prep",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "third_party",
   "on_enter": {"type": "silent"},
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
     "code": {"type": "string", "default": "vars['close_outcome'] = 'not_reached'\nvars['close_reason'] = 'no_callback'\n"},
     "timeout_ms": {"type": "number", "default": 10000}}}}}
   ],
   "transitions": [{"target_node": "third_party", "description": "always", "condition": {"operator": "always"}}]
  },
  "third_party": {
   "name": "third_party",
   "node_type": "conversation",
   "on_enter": {"type": "tts", "text": "Thank you. When can {{title}} {{last_name}} be reached?"},
   "on_enter_first_entry_only": true,
   "task_message": "You are not speaking with the customer. Do not say why you are calling and say nothing beyond your opening sentence. The person may not answer security questions and may not be told anything about the account, even if they offer to pay. Ask when {{title}} {{last_name}} can be reached. {{callback_window_text}} When they give a day and time inside that window, call schedule_callback with date YYYY-MM-DD and time HH:MM. If the day or time is outside the window, ask once for another time. If the second answer is also outside it, do not schedule: thank them and say goodbye. If they say the customer has died, say exactly: I am sorry for your loss. Then say goodbye. After every tool result, either speak or call the next tool. Call one tool per message. Follow what_to_do_next in a tool result. Call end_call right after your goodbye.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {"name": "schedule_callback", "handler": "__function__:api_call", "description": "Book a callback. CALL it as soon as the person gives a day and time inside the allowed window.", "parameters": {"type": "object", "properties": {
     "url": {"type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/schedule_callback"},
     "method": {"type": "string", "default": "POST"},
     "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
     "body": {"type": "object", "required": ["customer_id", "date", "time"], "properties": {
      "customer_id": {"type": "string", "default": "{{customer_id}}"},
      "date": {"type": "string", "description": "The callback day as YYYY-MM-DD, inside the window.", "default": "{{cb_date}}"},
      "time": {"type": "string", "description": "The callback time as HH:MM (24 hours), inside the window.", "default": "{{cb_time}}"}}}}}},
     "pre_process_code": "try:\n    b = config.get('body')\n    if isinstance(b, dict):\n        t = str(b.get('time') or '').strip().replace('.', ':')\n        if ':' in t:\n            h, m = t.split(':')[0], t.split(':')[1]\n            b['time'] = h.strip().zfill(2) + ':' + m.strip()[:2].zfill(2)\n        b['date'] = str(b.get('date') or '').strip()[:10]\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict) and str(d.get('ok')).lower() == 'true':\n        vars['close_outcome'] = 'not_reached'\n        vars['close_reason'] = 'callback'\n        vars['call_state'] = 'callback_booked'\n        d['what_to_do_next'] = 'Booked. Confirm the day and time, thank them and say goodbye, then call end_call.'\n    elif isinstance(d, dict):\n        d['what_to_do_next'] = 'NOT booked. Do not say it was booked. Ask once for another time inside the window.'\n    else:\n        result['what_to_do_next'] = 'NOT booked. Do not say it was booked. Try schedule_callback once more.'\nexcept Exception:\n    pass\n"},
    {"type": "function", "config": {"timeoutMs": 10000}, "function": {"name": "end_call", "handler": "__function__:end_call", "description": "Ends the call. CALL it right after you said goodbye, with no other text.", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}
   ],
   "extraction_schema": [
    {"name": "third_party_done", "type": "string", "enum_values": ["stay", "no_time", "wrong_number", "deceased"], "description": "no_time when the person gave no day and time inside the window after being asked a second time; wrong_number when they say the number does not belong to the customer; deceased when they say the customer has died; else stay.", "min_confidence": 0.7}
   ],
   "max_node_turns": 6,
   "max_turn_transition": "end_goodbye",
   "transitions": [
    {"target_node": "end_goodbye", "description": "Callback booked", "condition": {"logic": "or", "conditions": [{"variable": "call_state", "operator": "equals", "operand": "callback_booked"}]}},
    {"target_node": "wrong_prep", "description": "Wrong number", "condition": {"logic": "or", "conditions": [{"variable": "third_party_done", "operator": "equals", "operand": "wrong_number"}]}},
    {"target_node": "deceased_prep", "description": "Customer died", "condition": {"logic": "or", "conditions": [{"variable": "third_party_done", "operator": "equals", "operand": "deceased"}]}},
    {"target_node": "end_goodbye", "description": "No time in the window", "condition": {"logic": "or", "conditions": [{"variable": "third_party_done", "operator": "equals", "operand": "no_time"}]}}
   ]
  },
  "identity": {
   "name": "identity",
   "node_type": "conversation",
   "on_enter": {"type": "tts", "text": "Thank you. Before we continue, I need to ask two security questions. First, what is your date of birth?"},
   "on_enter_first_entry_only": true,
   "task_message": "Ask the two security questions one at a time: first the date of birth, then the last four digits of the phone number on file. Call verify_identity once for each answer: field date_of_birth with the answer as YYYY-MM-DD (convert spoken dates; a date given only as numbers is day, then month, then year), or field phone_last4 with four digits. Say nothing about the reason for the call. If the customer does not want to answer, or asks what the call is about instead of answering, explain once: These questions protect your account. Then ask again. No account details before both questions pass. After every tool result, either speak or call the next tool. Call one tool per message. Follow what_to_do_next in a tool result.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 1}, "function": {"name": "verify_identity", "handler": "__function__:api_call", "description": "Check one security answer. CALL it every time the customer answers a security question.", "parameters": {"type": "object", "properties": {
     "url": {"type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/verify_identity"},
     "method": {"type": "string", "default": "POST"},
     "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
     "body": {"type": "object", "required": ["customer_id", "field", "answer"], "properties": {
      "customer_id": {"type": "string", "default": "{{customer_id}}"},
      "field": {"type": "string", "enum": ["date_of_birth", "phone_last4"], "description": "Which question was answered.", "default": "{{id_field}}"},
      "answer": {"type": "string", "description": "date_of_birth: YYYY-MM-DD (numbers only are day, month, year). phone_last4: four digits.", "default": "{{id_answer}}"}}}}}},
     "pre_process_code": "import re\ntry:\n    b = config.get('body')\n    if isinstance(b, dict):\n        a = str(b.get('answer') or '').strip()\n        if b.get('field') == 'phone_last4':\n            digits = ''.join(c for c in a if c.isdigit())\n            b['answer'] = digits[-4:] if len(digits) >= 4 else digits\n        elif b.get('field') == 'date_of_birth':\n            m = re.match(r'^(\\d{1,2})[./ -](\\d{1,2})[./ -](\\d{4})$', a)\n            if m:\n                b['answer'] = m.group(3) + '-' + m.group(2).zfill(2) + '-' + m.group(1).zfill(2)\nexcept Exception:\n    pass\n",
     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    sc = str(result.get('status_code') or '')\n    if not isinstance(d, dict) or sc.startswith('5'):\n        result['what_to_do_next'] = 'The check did not go through and nothing was counted. Call verify_identity again with the same answer.'\n    elif str(d.get('all_verified')).lower() == 'true':\n        vars['id_state'] = 'passed'\n        d['what_to_do_next'] = 'Both questions passed. Say thank you in a few words only.'\n    elif str(d.get('wrong_answers_left')) == '0':\n        vars['id_state'] = 'failed'\n        d['what_to_do_next'] = 'The check failed. Say nothing about the account.'\n    elif d.get('hint') == 'day_month_swapped':\n        d['what_to_do_next'] = 'Ask the customer to say the month of birth as a word, then check again. This does not count as a wrong answer.'\n    elif str(d.get('ok')).lower() == 'false':\n        d['what_to_do_next'] = 'The answer could not be read. Ask the same question again.'\n    elif str(d.get('verified')).lower() == 'true':\n        d['what_to_do_next'] = 'Correct. Now ask for the last four digits of the phone number on file.'\n    else:\n        d['what_to_do_next'] = 'That answer is not correct. Ask the same question once more.'\nexcept Exception:\n    pass\n"},
