     "pre_process_code": "import re\ntry:\n    b = config.get('body')\n    if isinstance(b, dict):\n        a = str(b.get('answer') or '').strip()\n        if b.get('field') == 'phone_last4':\n            digits = ''.join(c for c in a if c.isdigit())\n            b['answer'] = digits[-4:] if len(digits) >= 4 else digits\n        elif b.get('field') == 'date_of_birth':\n            m = re.match(r'^(\\d{1,2})[./ -](\\d{1,2})[./ -](\\d{4})$', a)\n            if m:\n                b['answer'] = m.group(3) + '-' + m.group(2).zfill(2) + '-' + m.group(1).zfill(2)\nexcept Exception:\n    pass\n",
