    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 1}, "function": {"name": "verify_identity", "handler": "__function__:api_call", "description": "Check one security answer. CALL it every time the customer answers a security question.", "parameters": {"type": "object", "properties": {
     "url": {"type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/verify_identity"},
