H = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('cannot read now')

def is_business_day(d, holidays):
    return d.weekday() < 5 and d not in holidays

try:
    now = parse_now(vars.get('now'))
    today = now.date()
    hol = set(datetime.date.fromisoformat(x) for x in H)
    nxt = today + datetime.timedelta(days=1)
    while not is_business_day(nxt, hol):
        nxt = nxt + datetime.timedelta(days=1)
    ok = False
    try:
        d = datetime.date.fromisoformat(str(vars.get('cb_date') or '').strip()[:10])
        t = str(vars.get('cb_time') or '').strip().replace('.', ':')
        hh, mm = int(t.split(':')[0]), int((t.split(':') + ['0'])[1][:2] or 0)
        slot = datetime.datetime(d.year, d.month, d.day, hh, mm)
        in_hours = (hh, mm) >= (10, 0) and (hh, mm) <= (19, 0)
        ok = in_hours and slot > now and d in (today, nxt)
        vars['cb_date_ok'] = d.isoformat()
        vars['cb_time_ok'] = '%02d:%02d' % (hh, mm)
    except Exception:
        ok = False
    if ok:
        vars['cb_state'] = 'book'
    else:
        n = int(vars.get('cb_out_count') or 0) + 1
        vars['cb_out_count'] = str(n)
        vars['cb_state'] = 'no_callback' if n >= 2 else 'retry'
        vars['cb_text'] = 'I am sorry, that time is not possible. ' + str(vars.get('callback_window_text') or '') + ' Which other time would suit?'
except Exception:
    vars['cb_state'] = 'no_callback'
vars['third_party_done'] = 'stay'
