 and 19:00 on the next business day.'\n    vars['today_spoken'] = ''\nvars['close_outcome'] = 'not_reached'\nvars['close_reason'] = 'unclear'\nvars['promise_count'] = '0'\nvars['call_state'] = 'open'\nvars['id_state'] = 'open'\nvars['neg_state'] = 'none'\nvars['transfer_state'] = 'none'\nvars['record_result'] = 'none'\nvars['record_tries'] = '0'\nvars['topic'] = 'none'\n"},
