   "pre_actions": [
    {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {"type": "object", "properties": {
     "code": {"type": "string", "default": "import datetime\nimport json\n\nWEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']\nMONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']\nH = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']\n\ndef parse_now(value):\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now')\n\ndef is_business_day(d, holidays):\n    return d.weekday() < 5 and d not in holidays\n\ndef next_business_day(d, holidays):\n    d = d + datetime.timedelta(days=1)\n    while not is_business_day(d, holidays):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef add_business_days(d, n, holidays):\n    for _ in range(int(n)):\n        d = next_business_day(d, holidays)\n    return d\n\ndef week_monday(d):\n    return d - datetime.timedelta(days=d.weekday())\n\ndef last_business_day_of_week(d, holidays):\n    day = week_monday(d) + datetime.timedelta(days=4)\n    while day >= week_monday(d):\n        if is_business_day(day, holidays):\n            return day\n        day = day - datetime.timedelta(days=1)\n    return None\n\ndef spoken_date(d):\n    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()\n\ndef money(amount):\n    return '{:,.2f}'.format(round(float(amount), 2))\n\ndef as_list(value):\n    if isinstance(value, list):\n        return value\n    if isinstance(value, str):\n        try:\n            value = json.loads(value)\n        except ValueError:\n            return []\n    if isinstance(value, dict):\n        return [value]\n    return value if isinstance(value, list) else []\n\ndef list_from_vars(vars, name, prefixes):\n    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []\n    if found:\n        return found\n    for prefix in prefixes:\n        rows = dict()\n        start = prefix + '.'\n        for key, value in vars.items():\n            if not str(key).startswith(start):\n                continue\n            rest = str(key)[len(start):]\n            idx, _, field = rest.partition('.')\n            if idx.isdigit():\n                if field:\n                    rows.setdefault(int(idx), dict())[field] = value\n                else:\n                    rows[int(idx)] = value\n        if rows:\n            return [rows[i] for i in sorted(rows)]\n        whole = vars.get(prefix)\n        if whole not in (None, ''):\n            got = as_list(whole)\n            if got:\n                return got\n    return []\n\ntry:\n    now = parse_now(vars.get('now'))\n    today = now.date()\n    hol = set(datetime.date.fromisoformat(x) for x in H)\n    prods = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])\n    p = prods[0]\n    typ = str(p.get('type') or '')\n    if typ == 'credit_card':\n        label = 'credit card ending ' + str(p.get('card_last4') or '')\n        floor = p.get('minimum_payment')\n    elif typ == 'car_loan':\n        label = 'car loan'\n        floor = p.get('instalment_amount')\n    else:\n        label = 'personal loan'\n        floor = p.get('instalment_amount')\n    past_due = round(float(p.get('past_due') or 0), 2)\n    floor = round(float(floor or 0), 2)\n    days = int(float(p.get('days_late') or 0))\n    if days <= 7:\n        n, attempts, band = 12, 1, 'early'\n    else:\n        n, attempts, band = 7, 2, 'late'\n    deadline = add_business_days(today, n, hol)\n    wk = last_business_day_of_week(today, hol)\n    if wk is None or wk <= today:\n        wk = last_business_day_of_week(today + datetime.timedelta(days=7), hol)\n    a1 = min(wk, deadline) if wk else deadline\n    rows = []\n    for i in range(0, 22):\n        d = today + datetime.timedelta(days=i)\n        rows.append('- ' + spoken_date(d) + ' = ' + d.isoformat() + (', business day' if is_business_day(d, hol) else ', NOT a business day') + ('' if d <= deadline else ', after the latest date'))\n    vars['facts_json'] = json.dumps(dict(product_id=str(p.get('product_id') or ''), label=label, past_due=past_due, floor=floor, deadline=deadline.isoformat(), attempt1=a1.isoformat(), attempts=attempts, days=days, band=band))\n    vars['facts_text'] = ('Today is ' + spoken_date(today) + ' (' + today.isoformat() + '). Product: ' + label + '. Past-due amount: ' + money(past_due) + '. Days late: ' + str(days) + '. Lowest amount that can be recorded: ' + money(floor) + '. Latest promise date: ' + spoken_date(deadline) + '.\\nCalendar (this week is the week of today; next week is the following calendar week):\\n' + '\\n'.join(rows))\n    vars['debt_text'] = 'Thank you. I am calling from the collections team about a late payment on your ' + label + '. The past-due amount is ' + money(past_due) + ', and it is ' + str(days) + ' days late. Can you make this payment today?'\n    vars['neg_json'] = json.dumps(dict(cur_amount=past_due, cur_date=today.isoformat(), used=0, refused=[]))\n    vars['promise_product_id'] = str(p.get('product_id') or '')\n    vars['offer_text'] = 'Can you make this payment today?'\n    vars['readback_text'] = ''\n    vars['facts_state'] = 'ok'\nexcept Exception:\n    vars['facts_json'] = '{}'\n    vars['facts_text'] = 'The account details could not be read.'\n    vars['debt_text'] = 'I am sorry, I cannot see the account details right now.'\n    vars['offer_text'] = ''\n    vars['facts_state'] = 'error'\n"},
     "timeout_ms": {"type": "number", "default": 10000}}}}}
